import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, float, vec3, uniform, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-quote-panel';
  group.position.set(-2.5, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorTex = ctx.textureLoader.load(imageUrl);
  const depthTex = ctx.textureLoader.load(depthUrl);
  colorTex.colorSpace = THREE.SRGBColorSpace;

  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasScaleX = rect.w / 2048;
  const atlasScaleY = rect.h / 2048;
  const atlasOffsetX = rect.x / 2048;
  const atlasOffsetY = rect.y / 2048;

  const geometry = new THREE.PlaneGeometry(2.2, 1.375, 64, 64);

  const displacementStrength = uniform(float(0.12));
  const colorNode = texture(colorTex, uv());
  const depthSample = texture(depthTex, uv());

  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorNode = colorNode;
  material.metalness = 0.4;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.4;

  const displaced = positionLocal.add(
    normalLocal.mul(depthSample.r.sub(0.5).mul(displacementStrength))
  );
  material.positionNode = displaced;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'quote-parallax-mesh';
  group.add(mesh);

  // subtle accent rim light frame
  const rimGeo = new THREE.PlaneGeometry(2.28, 1.44);
  const rimMat = new THREE.MeshBasicNodeMaterial();
  rimMat.colorNode = vec3(1.0, 0.165, 0.219);
  rimMat.transparent = true;
  rimMat.opacity = 0.08;
  const rim = new THREE.Mesh(rimGeo, rimMat);
  rim.position.z = -0.01;
  group.add(rim);

  ctx.primitives['parallax-scroll'](group, { intensity: 0.4, trigger: 'scroll' });
  ctx.primitives['depth-rotate'](mesh, { maxDeg: 8, trigger: 'hover' });

  // weighted-settle entrance
  group.scale.set(0.001, 0.001, 0.001);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.6,
    ease: 'power4.out',
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.3,
    ease: 'power2.out',
  });

  const timelines = [settleTl];

  let hoverTl = null;
  const baseY = group.position.y;

  const onHover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };

  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
    timelines.push(pressTl);

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { source: 'home-quote-panel' });
    }
  };

  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (hoverTl) hoverTl.kill();
    geometry.dispose();
    rimGeo.dispose();
    material.dispose();
    rimMat.dispose();
    colorTex.dispose();
    depthTex.dispose();
  };

  return group;
}
